"""Base-n integer formatting helpers (pure stdlib)."""

_DIGITS = "0123456789abcdef"


def to_base(n: int, b: int) -> str:
    """Render the integer ``n`` in base ``b`` (2..16) using digits 0-9a-f."""
    if n == 0:
        return "0"

    out = []
    while n > 0:
        out.append(_DIGITS[n % b])
        n //= b
    return "".join(reversed(out))
